"""Offline, self-contained experiment relations dashboard (no remote assets)."""
from __future__ import annotations

import json
from pathlib import Path


def write_relations_report(payload: dict, directory: str | Path) -> Path:
    """Write a safe standalone dashboard plus its refreshable JSON data file.

    Network lines encode the supplied *similarity*, whereas the heatmap displays
    supplied within-cohort cell-level rank correlations. The renderer never
    estimates additional measurements, fills missing values, or runs a model.
    """
    target = Path(directory)
    target.mkdir(parents=True, exist_ok=True)
    assets = Path(__file__).with_name("assets")
    stylesheet = (assets / "relations.css").read_text(encoding="utf-8")
    script = (assets / "relations.js").read_text(encoding="utf-8")
    raw_json = json.dumps(payload, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    embedded = raw_json.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    page = _HTML.replace("__RELATIONS_CSS__", stylesheet).replace("__RELATIONS_SCRIPT__", script).replace("__RELATIONS_DATA__", embedded)
    data_temp = target / "data.json.tmp"
    data_temp.write_text(raw_json, encoding="utf-8")
    data_temp.replace(target / "data.json")
    output = target / "index.html"
    page_temp = target / "index.html.tmp"
    page_temp.write_text(page, encoding="utf-8")
    page_temp.replace(output)
    return output


